### Still present in v1.3.0

Confirmed this bug persists in v1.3.0. The loop exit condition is unchanged:

```
$ strings /usr/local/bin/opencode | grep 'lastUser.id < lastAssistant.id'
if (lastAssistant?.finish && !["tool-calls", "unknown"].includes(lastAssistant.finish) && lastUser.id < lastAssistant.id) {
```

PRs #17010 and #17149 (which fix this) are still open and unreviewed.

### Concrete trigger: remote `opencode web` with cross-machine clock skew

This reliably reproduces when `opencode web` runs on a remote server (e.g. Kubernetes) and the browser is on a different machine. The browser-generated user `messageID` encodes `Date.now()` from the client clock; the assistant `messageID` uses the server clock. Even a few ms of skew where the browser is ahead causes `lastUser.id > lastAssistant.id`, so the loop never breaks.

Does NOT reproduce when browser and server share the same machine (local `opencode web`).

### Workaround: HTTP delay proxy

For anyone stuck on this, here's a minimal Node.js proxy (~40 lines) that sits between the browser and `opencode web`. It only delays `POST /session/*/prompt_async` requests by exactly the clock skew — all other HTTP and WebSocket traffic passes through instantly.

```javascript
"use strict";
const http = require("http");
const TARGET = { host: "127.0.0.1", port: parseInt(process.env.TARGET_PORT || "3000") };
const LISTEN_PORT = parseInt(process.env.LISTEN_PORT || "8080");
const PROMPT_RE = /\/session\/[^/]+\/prompt(?:_async)?$/;
const MASK48 = (1n << 48n) - 1n;

function calcDelay(messageID) {
  if (!messageID?.startsWith("msg_") || messageID.length < 16) return 0;
  const hex = messageID.slice(4, 16);
  if (!/^[0-9a-f]{12}$/i.test(hex)) return 0;
  try {
    const idEnc = BigInt("0x" + hex);
    const nowEnc = (BigInt(Date.now()) * 0x1000n + 1n) & MASK48;
    return idEnc > nowEnc ? Math.min(Number((idEnc - nowEnc) / 0x1000n), 5000) : 0;
  } catch { return 0; }
}

function proxy(req, res, body) {
  const p = http.request({ ...TARGET, method: req.method, path: req.url,
    headers: { ...req.headers, host: `${TARGET.host}:${TARGET.port}` }
  }, (r) => { res.writeHead(r.statusCode, r.headers); r.pipe(res); });
  p.on("error", () => { if (!res.headersSent) { res.writeHead(502); res.end("Bad Gateway"); } });
  body ? p.end(body) : req.pipe(p);
}

http.createServer((req, res) => {
  if (req.method === "POST" && PROMPT_RE.test(req.url)) {
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => {
      const body = Buffer.concat(chunks);
      let delay = 0;
      try { const j = JSON.parse(body); if (j.messageID) delay = calcDelay(j.messageID); } catch {}
      if (delay > 0) setTimeout(() => proxy(req, res, body), delay);
      else proxy(req, res, body);
    });
  } else proxy(req, res);
}).on("upgrade", (req, sock, head) => {
  const p = http.request({ ...TARGET, method: req.method, path: req.url, headers: req.headers });
  p.on("upgrade", (r, up, uh) => {
    let h = "HTTP/1.1 101 Switching Protocols\r\n";
    for (let i = 0; i < r.rawHeaders.length; i += 2) h += r.rawHeaders[i] + ": " + r.rawHeaders[i+1] + "\r\n";
    sock.write(h + "\r\n"); if (uh.length) sock.write(uh); if (head.length) up.write(head);
    sock.pipe(up); up.pipe(sock);
    sock.on("error", () => up.destroy()); up.on("error", () => sock.destroy());
  });
  p.on("error", () => sock.destroy());
  p.end();
}).listen(LISTEN_PORT, "0.0.0.0", () =>
  console.log("[proxy] :" + LISTEN_PORT + " -> " + TARGET.host + ":" + TARGET.port)
);
```

Usage: `TARGET_PORT=3000 LISTEN_PORT=8080 node proxy.js`, point browser at port 8080.

@thdxr hey there! I saw you are assigned to this issue. Just wondering if you have any thoughts? I am happy to plan out and do the PR for this. We are desperate for this addition to OC and are willing to invest the labor to make it happen.

Because it will probably involve adding settings to the `opencode.json` file, it would be very helpful to have some steering from the Opencode team on the best approach here.

